package dev.alien.client.cosmetic.pet;

import com.google.gson.Gson;
import dev.alien.client.config.*;
import dev.alien.client.cosmetic.*;
import dev.alien.client.cosmetic.mesh.*;
import java.util.*;
import org.junit.*;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

public class PetTest {
    @Rule public TemporaryFolder temp=new TemporaryFolder();
    @Test public void oldProfilesDoNotEnableMascotsOrChangeExistingLooks(){CosmeticConfig.Accessory a=new Gson().fromJson("{\"aura\":true,\"hat\":\"SAKURA\",\"pet\":null}",CosmeticConfig.Accessory.class);a.normalize();assertNotNull(a.pet);assertFalse(a.pet.enabled);assertEquals("SAKURA",a.hat);assertTrue(a.aura);}
    @Test public void corruptImportsHaveFiniteBoundedPreferences(){PetDesign p=new PetDesign();p.mode="missing";p.color=-1;p.size=Float.NaN;p.height=Float.POSITIVE_INFINITY;p.distance=99;p.speed=-5;p.normalize();assertEquals("Follow",p.mode);assertEquals(0xffffff,p.color);assertEquals(1,p.size,0);assertEquals(1.15f,p.height,0);assertEquals(2,p.distance,0);assertEquals(.4f,p.speed,0);}
    @Test public void palettesAreDistinctAndUnknownPaletteDoesNotMutate(){Set<Integer> colors=new HashSet<Integer>();for(String n:PetDesign.PRESETS){PetDesign p=new PetDesign();assertTrue(p.applyPreset(n));assertTrue(p.enabled);assertTrue(colors.add(p.color));}PetDesign p=new PetDesign();String before=new Gson().toJson(p);assertFalse(p.applyPreset("unknown"));assertEquals(before,new Gson().toJson(p));}
    @Test public void profilesAndLookSlotsKeepIndependentMascotPreferences()throws Exception{ConfigStore s=new ConfigStore(temp.newFolder());s.load();CosmeticConfig.Accessory a=s.config().cosmetics.self;a.pet.applyPreset("Mint");a.pet.mode="Orbit";a.pet.reactEmotes=false;a.pet.size=1.25f;s.config().cosmetics.saveLook(1,a);a.pet.color=0x123456;assertNotEquals(a.pet.color,s.config().cosmetics.loadLook(1).pet.color);s.config().emotes.slots[0]="take_the_l";a.aura=true;a.auraDesign.applyPreset("Arcane");s.saveProfile("mascot");String text=s.profileJson("mascot");assertFalse(text.contains("previousTime"));assertFalse(text.contains("sleeping"));s.resetDefaults();s.importProfileJson("copy",text);assertTrue(s.loadProfile("copy"));a=s.config().cosmetics.self;assertTrue(a.pet.enabled&&a.aura);assertEquals("Orbit",a.pet.mode);assertEquals(1.25f,a.pet.size,0);assertFalse(a.pet.reactEmotes);assertEquals("take_the_l",s.config().emotes.slots[0]);assertFalse(s.config().combat.enabled);}
    @Test public void followIsDampedAndConvergesToTheRealOwner(){PetDesign c=new PetDesign();PetMotion m=new PetMotion();m.update(c,.05,0,0,0,0,0,false,true);double first=m.x(1);m.update(c,.05,3,0,0,0,4,false,true);assertTrue(m.x(1)>first&&m.x(1)<3-c.distance);for(int i=0;i<100;i++)m.update(c,.05,3,0,0,0,0,false,true);assertEquals(3-c.distance,m.x(1),1e-6);assertEquals(c.height,m.y(1),1e-6);}
    @Test public void teleportsSnapBothRenderEndpoints(){PetDesign c=new PetDesign();PetMotion m=new PetMotion();m.update(c,.05,0,0,0,0,0,false,true);m.update(c,.05,1000,70,1000,180,0,false,true);assertEquals(m.x(1),m.x(0),0);assertEquals(m.y(1),m.y(0),0);assertEquals(m.z(1),m.z(0),0);assertEquals(1000+c.distance,m.x(1),1e-4);}
    @Test public void shoulderAndOrbitProduceDifferentActualTargets(){PetDesign c=new PetDesign();c.mode="Shoulder";PetMotion a=new PetMotion();a.update(c,.05,0,0,0,0,0,false,true);assertEquals(-.42,a.x(1),1e-6);assertEquals(1.6,a.y(1),1e-6);c.mode="Orbit";PetMotion b=new PetMotion();b.update(c,.05,0,0,0,0,0,false,true);double x=b.x(1);for(int i=0;i<50;i++)b.update(c,.05,0,0,0,0,0,false,true);assertTrue(Math.abs(x-b.x(1))>.4);}
    @Test public void idleSleepWakesOnMovementAndCanBeDisabled(){PetDesign c=new PetDesign();PetMotion m=new PetMotion();for(int i=0;i<190;i++)m.update(c,.05,0,0,0,0,0,false,true);assertTrue(m.sleeping(1)>.95);for(int i=0;i<15;i++)m.update(c,.05,0,0,0,0,5,false,true);assertTrue(m.sleeping(1)<.01&&m.movement(1)>.95);c.sleep=false;for(int i=0;i<200;i++)m.update(c,.05,0,0,0,0,0,false,true);assertTrue(m.sleeping(1)<.001);}
    @Test public void actualEmoteInputFeedsOnlyTheEnabledReaction(){PetDesign c=new PetDesign();PetMotion m=new PetMotion();for(int i=0;i<25;i++)m.update(c,.05,0,0,0,0,0,true,true);assertTrue(m.dancing(1)>.99);c.reactEmotes=false;for(int i=0;i<25;i++)m.update(c,.05,0,0,0,0,0,true,true);assertTrue(m.dancing(1)<.001);}
    @Test public void renderingSamplesCannotAdvanceSimulation(){PetDesign c=new PetDesign();PetMotion m=new PetMotion();m.update(c,.05,0,0,0,0,4,true,true);double time=m.time(1),x=m.x(1);PetPose pose=new PetPose();for(int i=0;i<1000;i++)m.pose((i%10)/10f,true,pose);assertEquals(time,m.time(1),0);assertEquals(x,m.x(1),0);}
    @Test public void staticTargetAndReactionDoNotDependOnTickSubdivision(){PetDesign c=new PetDesign();PetMotion a=new PetMotion(),b=new PetMotion();for(int i=0;i<100;i++){a.update(c,.05,0,0,0,0,4,true,true);b.update(c,.025,0,0,0,0,4,true,true);b.update(c,.025,0,0,0,0,4,true,true);}assertEquals(a.time(1),b.time(1),1e-9);assertEquals(a.movement(1),b.movement(1),1e-5);assertEquals(a.dancing(1),b.dancing(1),1e-5);}
    @Test public void invalidTimeDoesNotPoisonMotionAndAnimationOffIsNeutral(){PetDesign c=new PetDesign();PetMotion m=new PetMotion();m.update(c,Double.NaN,0,0,0,0,0,false,true);assertEquals(0,m.time(1),0);m.update(c,.05,0,0,0,Float.MAX_VALUE,Double.NaN,false,true);assertTrue(Float.isFinite(m.yaw(1)));PetPose p=new PetPose();p.sample(Double.NaN,Float.NaN,Float.NaN,Float.NaN,false);assertEquals(1,p.eyes,0);assertEquals(0,p.bob,0);assertEquals(0,p.rightArm,0);}
    @Test public void blinkAndWaveStayFiniteAndHaveVisibleJointMotion(){PetPose p=new PetPose();float min=1,max=0;Set<Integer> arms=new HashSet<Integer>();for(int i=0;i<1000;i++){p.sample(i*.01,1,0,1,true);min=Math.min(min,p.eyes);max=Math.max(max,p.eyes);assertTrue(Float.isFinite(p.bob)&&Float.isFinite(p.antenna));assertTrue(Math.abs(p.rightArm)<105);arms.add(Math.round(p.rightArm));}assertTrue(min<.1&&max>.9&&arms.size()>20);}
    @Test public void cachedRoundedMeshesAreFiniteAndBounded(){int vertices=0;for(Mesh m:new Mesh[]{PetMeshes.HEAD,PetMeshes.BODY,PetMeshes.ARM,PetMeshes.FOOT,PetMeshes.EYE,PetMeshes.STEM,PetMeshes.TIP,PetMeshes.RING}){assertTrue(m.vertexCount()>20);assertEquals(0,m.vertexCount()%3);vertices+=m.vertexCount();for(int i=0;i<m.vertexCount();i++){assertTrue(Float.isFinite(m.x(i))&&Float.isFinite(m.y(i))&&Float.isFinite(m.z(i)));assertTrue(Math.abs(m.x(i))<4&&Math.abs(m.y(i))<4&&Math.abs(m.z(i))<4);}}assertTrue(vertices<6000);}
}
